INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atomic-robo-kid', 11921, '1988-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vfg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aob3o0a9gces4ed2k0vn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomic Robo-Kid', 'Atomic Robo-Kid is a horizontally scrolling shooter released in arcades by UPL. The player controls the titular character through six stages of increasing difficulty, facing an alien "governor" boss (which are so large as to be considered levels in and of themselves, as some of the bosses take up several screens) at the end of each level, followed by a "duel" level against other Robo-Kid sized robots. Many levels branch into others, giving the player the choice over which zone to enter next, increasing replayability.' FROM games WHERE igdb_id = 11921 ON CONFLICT (game_id, language_code) DO NOTHING;
