INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Chess', 'Battle Chess was developed by Interplay as their first project after severing ties with Electronic Arts. They designed it for the Amiga in 1988, and it was released on the majority of the other systems in the late 1980s and early 1990s as well. It was widely successful, and resulted in two follow-ups, many copy-cat games, and a remake for Steam on PC. The only significant criticism the game received was the weak chess AI, as it was not until the mid 1990s that chess ai began to consistently win against strong opponents.' FROM games WHERE igdb_id = 2603 ON CONFLICT (game_id, language_code) DO NOTHING;
