INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: The Caped Crusader', 'The penguin is back, and he''s set himself up as a respectable umbrella merchant. Or has he? Could the umbrella factory be just a cover for his plot to take over the world with an army of robotic penguins? As Batman you must match clues you''ve collected to locate the master computer and - POW! ZAP! CRUNCH! - Put an end to the demented squawkings of that overweight birdbrain. But that''s not all! As soon as you''ve taken care of the Penguin, the Joker pulls off his greatest feat of sleight of hand - he kidnaps Robin! At the scene of the crime, you must gather all the facts. Then, while the trail is still hot, you''re off on a crime solving adventure. Grab your batarang and rev up the Batmobile - because if you don''t reach Robin in a hurry, the last laugh will be on you! HA, HA, HA, HA!' FROM games WHERE igdb_id = 12401 ON CONFLICT (game_id, language_code) DO NOTHING;
