INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The NewZealand Story', 'Tiki, a sneaker-wearing kiwi who must save his lover Phee Phee and several of his other kiwi chick friends who have been kiwi-napped by a large blue leopard seal. The player has to navigate a scrolling maze-like level, at the end of which they release one of Tiki''s kiwi chick friends trapped in a cage.' FROM games WHERE igdb_id = 7628 ON CONFLICT (game_id, language_code) DO NOTHING;
