INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vigilante', 10444, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co685y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kv2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vigilante', 'On the baddest streets of the city they know your name. You are lean and mean... the karate master they call the Vigilante! Your turf was left alone. Your friends and neighbors lived in peace. Until the Rogue gang got too big for their britches. You chilled, hoping things wouldn''t get too rough. No such luck. They''ve taken your girlfriend Maria, and there''s only one thing you can do... get her back... anyway you can! You have fists of steel! Legs like pistons! And courage that just won''t quit! You will need all three because the Rogues are waiting with knives, guns and a whole bunch of nasty punks. And you''ll have to fight fast. If the Rogues make it back to their headquarters before you rescue Maria, all hope will be lost. But catch them first and you''ll fight the leader of the Rogues. Win Maria... and your turf... will remain safe. Feel any pressure? No way. You''re the Vigilante!' FROM games WHERE igdb_id = 10444 ON CONFLICT (game_id, language_code) DO NOTHING;
