INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rambo III', 'Rambo III is a series of video games based on the film of the same name. Like in the film, their main plots center on former Vietnam-era Green Beret John Rambo being recalled up to duty one last time to rescue his former commander, Colonel Sam Trautman, who was captured during a covert operation mission in Soviet Union-controlled Afghanistan. The console versions are developed and published by Sega, the PC DOS version was developed by Ocean and published by Taito and Ocean developed and published the rest (Atari ST, Amiga, Spectrum, C64, Amstrad). Taito also released an arcade game based on the film.' FROM games WHERE igdb_id = 12469 ON CONFLICT (game_id, language_code) DO NOTHING;
