INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Narc', 'Narc is a 1-2 player game, where your mission is to infiltrate the Mr. Big Corporation, the scourge of the underworld. To do this, you must get through the game''s eight stages, with over ten sectors like the junkyard, subway, drug lab, nursery, downtown, Sunset Strip, and even the corporation, where Mr. Big resides. In order to get through the stages, you are required to collect a number of safe cards, and insert them in the slot next to the stage exit. Each sector includes a map, and should be easy to read. For example, the blue or red dots represent you, and the white dots are the missile launchers, while the "E" indicates the exit.' FROM games WHERE igdb_id = 4010 ON CONFLICT (game_id, language_code) DO NOTHING;
