INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomic Runner', 'The player takes the role of Chelnov, a coal miner who miraculously survives the malfunction and explosion of a nuclear power plant. Chelnov''s body gains superhuman abilities due to the massive amount of radiation given off by the explosion, and a secret organization seeks to harness those abilities for its own evil purposes. Chelnov must battle and defeat the secret organization using his newfound abilities.' FROM games WHERE igdb_id = 46241 ON CONFLICT (game_id, language_code) DO NOTHING;
