INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-drift', 12719, '1988-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ht5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vq62lka0suykmscjcm5p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Drift', 'Power Drift is a kart racing game released in arcades by Sega in 1988. More technologically advanced than Sega''s earlier 2.5D racing games, like Hang-On (1985) and Out Run (1986), in Power Drift the entire world and track consist of sprites. The upgraded hardware of the Sega Y Board allows individual sprites and the background to be rotated–even while being scaled–making the visuals more dynamic. Designed and directed by Yu Suzuki, the game was a critical and commercial success upon release in arcades. It was subsequently ported to various home computers in Europe by Activision in 1989, followed by a PC Engine port published in Japan by Asmik Ace in 1990. It was not released on Sega consoles until the Sega Ages release for the Sega Saturn in 1998.' FROM games WHERE igdb_id = 12719 ON CONFLICT (game_id, language_code) DO NOTHING;
