INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Contra', 'Super Contra is a Run and Gun-style action game produced by Konami, originally released as a coin-operated arcade game in 1988. It is the sequel to the original Contra and the second game in the Contra series released for the arcades. Like in the original game, the game centers on soldiers Bill Rizer and Lance Bean, who are once again assigned to protect the Earth from an army of alien invaders. The game features standard side-scrolling stages, as well as all new overhead stages in lieu of the original game''s "3D" stages.' FROM games WHERE igdb_id = 4622 ON CONFLICT (game_id, language_code) DO NOTHING;
