INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Wolf', 'Snake and Eagle, two commandos of the Bloody Wolf special forces, receive instructions from their commander to destroy the enemy''s heavily armed base to rescue the President and any allies who have been reported as MIA. Based off the 1988 arcade game, this single-player, top-down, run and gun shooter takes a nod to Contra-style gameplay, allowing one of the two mercenaries to blast their way through eight levels of enemy opposition armed with only a knife and a machine gun. Along the way, new weapons such as shotguns, bazookas, flash bombs and grenades grenades can be added to the arsenal, as well as health and defensive power-ups. Players can even find a motorcycle to ride in some areas, or swim through certain parts of a level. The President and your fellow soldiers need you!' FROM games WHERE igdb_id = 42117 ON CONFLICT (game_id, language_code) DO NOTHING;
