INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('8-eyes', 1975, '1988-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44dz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpi0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8 Eyes', 'CONTROL MAN AND BIRD IN A FIGHT FOR THE EIGHT JEWELS OF POWER! After hundreds of years of chaos, mankind has finally emerged from the ruins of nuclear war. This world of the distant future has once again fluorished under the guidance of the Great King, who harnessed the power of the 8 Eyes to rebuild the planet. These strange jewels of power were formed at the eyes, or centers, of the eight nuclear explosions which nearly destroyed the Earth. In the wrong hands, the 8 Eyes could cause untold destruction...And now, they have been seized by the Great King''s eight Dukes, in a desperate bid to gain control of the world for themselves. They have banished the King to the nuclear wastelands, and already their squabbling threatens to plunge the world into war once again! The task of retrieving the 8 Eyes falls to you, Orin the Falconer, the bravest and mightiest of the King''s Guardsmen. With your fighting falcon, Cutrus, you must penetrate each of the eight Dukes'' castles. There you will face the Dukes'' soldiers, and battle strange nuclear mutants such as living skeletons, giant wasps, and mud men. You must defeat the monstrous Boss of each castle to retrieve the Jewel of Power he guards. Then, to complete your quest, return the 8 Eyes to the Altar of Peace to await the return on the Great King, so that he may finish the rebuilding of Earth. Your reward will be the the eternal gratitude of all mankind!' FROM games WHERE igdb_id = 1975 ON CONFLICT (game_id, language_code) DO NOTHING;
