INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy Force II', 'The peaceful and prosperous solar system Junos was located at the end of the Milky Way. Those who called its five planets home had no idea what was about to happen... Halcyon, ruler of the Fourth Empire, had Junos marked as its final target in the galactic massacre, and had sent the bulk of his attacking force in with a single purpose – the elimination of all life forms in the system, and the construction of a gigantic fortress on each of the five planets from which to rule the galaxy. Galaxy Force II is not a true sequel to the orginal game but a an enhanced version of the original. It was released roughly two months after the release of the first part thus making it obsolete.' FROM games WHERE igdb_id = 6799 ON CONFLICT (game_id, language_code) DO NOTHING;
