INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golgo 13: Top Secret Episode', 'The player takes on the role of Golgo 13 (also known as Duke Togo), an assassin whose objective is to destroy the leader of the Drek group. On the way, Golgo 13 must pass through several areas, including East Berlin, Athens, and Alexander Island, which is located off the coast of Antarctica. It is necessary to navigate several mazes in order to win, but one maze is a fake base with no way out. The mazes account for a large amount of the frustration players encounter with this game. The instruction manual contains maps for the mazes.' FROM games WHERE igdb_id = 48059 ON CONFLICT (game_id, language_code) DO NOTHING;
