INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cybernoid: The Fighting Machine', 'Cybernoid: The Fighting Machine is a shoot ''em up developed and published in 1987 by Hewson Consultants for the ZX Spectrum, and was then ported to the Amstrad CPC, Atari ST, Commodore 64, NES, and Amiga. It was programmed by Raffaele Cecco. The Sinclair ZX Spectrum and Atari ST versions featured a main theme by Dave Rogers, while the Commodore C64 version (later released on the Wii''s Virtual Console service) featured a completely different theme by Jeroen Tel.' FROM games WHERE igdb_id = 12024 ON CONFLICT (game_id, language_code) DO NOTHING;
