INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Captain Comic', 'The Adventures of Captain Comic is a platformer featuring a huge nonlinear playfield divided into several different terrains. As Comic, you must search throughout Tambi for power ups and items that will aid you in your quest to recover the three treasures. The Captain''s main weapon is ''Blastola Cola'', a can of drink that allows him to hurl fireballs at his foes. For each can that he finds, an additional fireball can be thrown.' FROM games WHERE igdb_id = 9528 ON CONFLICT (game_id, language_code) DO NOTHING;
