INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy II', 'Final Fantasy II is the second installment in the Final Fantasy series, developed and published by Squaresoft. It was directed by Hironobu Sakaguchi, with Yoshitaka Amano designing the characters and Nobuo Uematsu composing the score. It was notable for being one of the first story-intensive RPGs released for console systems, and introducing many series staples, including chocobos and a character named Cid. Its story is unrelated to the original FINAL FANTASY, and its gameplay is a major departure from the previous title for eliminating the traditional experience-based progression system.' FROM games WHERE igdb_id = 16474 ON CONFLICT (game_id, language_code) DO NOTHING;
