INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabal', 'Originating in the arcades, Cabal is a shooter where the protagonist runs back and forth along the bottom of the screen, ducking and dodging bullets and grenades from the enemy. The roll maneuver from the arcade was not implemented in the PC version. The player returns fire by moving a target around the screen which also moves the player character and may expose him to enemy fire.' FROM games WHERE igdb_id = 6317 ON CONFLICT (game_id, language_code) DO NOTHING;
