INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('advanced-dungeons-and-dragons-pool-of-radiance', 8732, '1988-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6jab.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvlk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Dungeons & Dragons: Pool of Radiance', 'Located on the northern shore of the Moonsea in the Forgotten Realms, the fabled city of Phlan had been overrun by monsters led by a mysterious leader. Your quest: discover the identity of this evil force and rid Phlan of its scourge. Pool of Radiance represents the first in a line of software created by SSI in collaboration with TSR - the producer of the legendary Advanced Dungeons & Dragons fantasy role-playing system.' FROM games WHERE igdb_id = 8732 ON CONFLICT (game_id, language_code) DO NOTHING;
