INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla: Monster of Monsters', 'The invaders from Planet X attack earth as part of their plan to conquer the entire universe, using a legion of space monsters. The earth sends Godzilla, the strongest monster on the earth, and Mothra, to defend itself. Godzilla advances through 8 battle stages to defeat a legion of space monsters controlled by Planet X. For the sake of the future of the earth, Godzilla''s fierce battle now begin...' FROM games WHERE igdb_id = 48161 ON CONFLICT (game_id, language_code) DO NOTHING;
