INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Famicom Wars', 'Famicom Wars is a Japanese-only video game for the Famicom (the Japanese name for the NES). It was designed by Nintendo R&D1 and programmed by Intelligent Systems and published by Nintendo. It spawned many sequels, five of which were released in America. It is the first game in the Nintendo Wars series. The gameplay can be compared to games in the Fire Emblem series, as both are in the turn based strategy genre, and both have been developed and published by the same companies (the Famicom Wars series was released first, however).' FROM games WHERE igdb_id = 72131 ON CONFLICT (game_id, language_code) DO NOTHING;
