INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('altered-beast', 2604, '1988-08-01', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25mp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1nq7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Altered Beast', 'Unleash metamorphic power. "Awaken, dead warrior!" cries Zeus, God of Thunder. And you rise. Called upon to live again, you kick, punch, grapple and tear at the inhuman and monstrous flesh of horrible, dangerous underworld henchmen out to do you wrong. Savagely intent upon rescuing Athena, daughter of Zeus, from the demon god Neff, you stalk the bowels of Hades and beyond. What you are now you will not be. You are the Altered Beast - bestowed with five formidable forces of transformation - each more ferocious, more overwhelming, than the last. By battling, conquering and capturing spirit balls, your metamorphic powers will grow. But to what end? The final confrontation. Your triumph over crocodile worms, hammer demons and grave masters brings on the horror of Neff himself. But boldness and cunning will be rewarded - in the ultimate Altered Beast! Transformation is the ultimate power.' FROM games WHERE igdb_id = 2604 ON CONFLICT (game_id, language_code) DO NOTHING;
