INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contra', 'This is the Family Computer (Famicom) port of Contra. Even if the American and the Japanese port look similar and share the same art style and engine, the Japanese version has added content, with more animations in the backgrounds, new cheat codes and, most importantly, story cutscenes explaining the plot of the game.' FROM games WHERE igdb_id = 186208 ON CONFLICT (game_id, language_code) DO NOTHING;
