INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toobin''', 'Toobin'' involves Biff and Jet racing their way down the rapids of a river, riding on tires. You rotate your tyre left or right, and drift as the current sends you, making sure to avoid the banks of the river, and the dividing lines in the middle. Hazards include crocodiles, stray logs and branches, and fishermen - you are armed with a limited supply of tin cans to take care of these. There are gates to slide through on the way down - these give you a points bonus. Each level has a strict time limit to adhere to, although there''s a kickin'' party at the end if you succeed.' FROM games WHERE igdb_id = 12867 ON CONFLICT (game_id, language_code) DO NOTHING;
