INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'Tetris is a puzzle game developed originally released for arcades. Players must stack differently shaped falling blocks to form and eliminate horizontal lines from the playing field. The game features several difficulty levels and two-player simultaneous play.' FROM games WHERE igdb_id = 178293 ON CONFLICT (game_id, language_code) DO NOTHING;
