INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Dudes vs. Dragon Ninja', 'Bad Dudes Vs. DragonNinja, often referred to simply as Bad Dudes (on the American NES port of the arcade original), and known in Japan simply as DragonNinja is a 1988 arcade game developed and published by Data East. It was also ported to many computer and game console home systems. Bad Dudes is a side-scrolling beat ''em up where the players are set in the role of the titular duo tasked with rescuing "President Ronnie" from ninja kidnappers. It was met with commercial success, and a generally positive to mixed critical reception. It has since become widely known for its general premise and introductory cut scene.' FROM games WHERE igdb_id = 18831 ON CONFLICT (game_id, language_code) DO NOTHING;
