INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Target: Renegade', 'Target: Renegade is a scrolling beat''em up (or flip-screen on certain versions) computer game released on the Amstrad CPC, Commodore 64 and ZX Spectrum systems in the late 1980s by Ocean Software on their "Imagine" label, as well as a Nintendo Entertainment System version published by Taito. The game is a sequel to Renegade and was followed by Renegade 3. When acquiring the license to convert the original arcade game Renegade to home computers, Ocean acquired the option to produce and release their own home-computer-only sequels to the game, and Target Renegade was the first of these sequels. On most formats, the game caters for one or two players and concerns itself with the adventures of a streetfighter (or a pair of identical streetfighters) known only as "Renegade", who seek(s) revenge against a local crime kingpin named "Mr. Big" for murdering his or their brother Matt. The player character varies, depending on the format, but is usually represented as topless apart from a leather vest and wearing jeans. Regardless of the format, the cover of the game and the title screen (as seen on the image to the right) portrays a topless street fighter performing a flying kick through a window. In keeping with video game box art and advertising of the era, the character shown in this illustration bears little relation to any character in the game itself. The actual picture is based on Martial Arts Legend Joe Lewis from the cover of his book The World''s Greatest Fighter Teaches You How To Master Bruce Lee''s Fighting System, but has been adjusted so as to fit in with the character of Renegade. The game comprises five levels, though details of enemies and weapons vary from one version to another (the NES version in particular is more like Double Dragon than the home computer versions). The NES and C64 versions of the game do not have a two-player co-operative mode.' FROM games WHERE igdb_id = 39060 ON CONFLICT (game_id, language_code) DO NOTHING;
