INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truxton', 'Truxton is a 1988 vertically scrolling, shoot ''em up arcade game developed by Toaplan, later ported to the Mega Drive (worldwide) and the PC Engine (Japan-only). Like many other scrolling shooters, the game is set in outer space, where the player takes control of a small spaceship across several planets. The game is played with an eight-way joystick and two buttons (a shot and a bomb button) through five large levels and their bosses (which then loop forever, at higher difficulties).' FROM games WHERE igdb_id = 4418 ON CONFLICT (game_id, language_code) DO NOTHING;
