INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest IV: The Perils of Rosella', 'King''s Quest IV: The Perils of Rosella is an adventure game in the King''s Quest series. Players control Princess Rosella, daughter of King Graham, as she embarks on a quest to save her father''s life and rescue a fairy kingdom. The game takes place in the land of Tamir, where Rosella must find a magical fruit to heal her ailing father while also helping the fairy queen Genesta reclaim her stolen talisman from the evil fairy Lolotte. Players navigate Rosella through various environments, solving puzzles and interacting with characters from folklore and fairy tales. King''s Quest IV introduces real-time elements and day-night cycles to the series, affecting gameplay and puzzle solutions. The game expands on the series'' narrative by focusing on a female protagonist and exploring new themes while maintaining the fantasy setting and puzzle-solving mechanics characteristic of the King''s Quest franchise.' FROM games WHERE igdb_id = 744 ON CONFLICT (game_id, language_code) DO NOTHING;
