INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Thunderbolt', 'Operation Thunderbolt is the exciting sequel to Operation Wolf. An airliner is hijacked by terrorists en-route from Paris to Boston, who threaten to kill all hostages on board if their mates aren''t released from jail. Instead of reaching its destination, the airliner makes a landing in Kalubya, Africa, and all the hostages are hidden in various locations. The authorities have asked the hero from Operation Wolf to rescue the hostages, but only this time, the hero brings his friend along for the ride. There are eight missions to complete in Operation Thunderbolt, and each one has you shooting down soldiers, choppers, and tanks. The gameplay varies every one or two missions. In some missions, you are driving a jeep or controlling a boat, while in others, you are walking while you''re shooting. You have a limited supply of ammo, and a limited supply of rocket bombs, but you can always stock up by shooting down crates falling from the sky, or by killing a cat or dog that get in the line of fire. Also from crates, you can get special items like bulletproof vests, rocket bombs, and different weapons.' FROM games WHERE igdb_id = 12191 ON CONFLICT (game_id, language_code) DO NOTHING;
