INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedball', 'Speedball is a futuristic football-like game which takes place on a steel walled floored pitch, 160 feet long by 90 feet wide. There are two teams, and the team scoring the most goals wins. There is a goal at each end of the pitch and a ball warp tunnel in each side of the wall. The warp tunnels can warp a ball from one tunnel to another. The ball is launched from the center of the pit by the automatic launcher in a random direction. There also bounce domes, off of which the ball will be deflected, but over which players are free to move.' FROM games WHERE igdb_id = 10151 ON CONFLICT (game_id, language_code) DO NOTHING;
