INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cybernoid II: The Revenge', 'Cybernoid II: The Revenge is a challenging flip-screen shoot ''em up that builds upon its predecessor. Players pilot the advanced Cybernoid craft on a mission to recover stolen cargo from pirate ships. The game features a diverse arsenal of weapons, including sideways-aiming guns, bouncing bombs, and smart bombs, which players must use strategically to overcome varying levels of hazards and unpredictable enemy behavior. Success hinges on collecting at least 1500 points of cargo while navigating through treacherous environments, often requiring quick decisions between engaging enemies and making timely escapes.' FROM games WHERE igdb_id = 12025 ON CONFLICT (game_id, language_code) DO NOTHING;
