INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jackal', 'Jackal, also distributed under the title of Top Gunner, is an overhead run-and-gun shooter by Konami released as an arcade video game in 1986. The player must maneuver an armed jeep in order to rescue prisoners of war (POWs) trapped in enemy territory.' FROM games WHERE igdb_id = 212707 ON CONFLICT (game_id, language_code) DO NOTHING;
