INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('double-dragon-ii-the-revenge', 6790, '1988-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gso.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2osh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Dragon II: The Revenge', 'The original arcade version of "Double Dragon II" is essentially an improved version of the first game. The biggest change in the game''s controls are in the replacement of the original''s punch and kick buttons with two directional-based attack buttons (Left Attack and Right Attack) similar to Renegade. Pressing the attack button of the player''s current direction will do a standard series of punches, while pressing the opposite attack button will perform a back kick. A few new moves are added as well, including a Hurricane Kick. Like in the original game, the arcade version of Double Dragon II is divided into four missions: a heliport, a lumber storehouse, a wheat field, and the new hideout of the boss. Each stage has its own boss character with his own theme. After defeating Willy (the final boss from the original game) in the fourth stage, the player will confront a double of their own character for the game''s final battle. If two players reach the end together, then both will each to have to face their own clone for the final battle.' FROM games WHERE igdb_id = 6790 ON CONFLICT (game_id, language_code) DO NOTHING;
