INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manhunter: New York', 'It has been over 2 years since the agressive Orbs attacked the Earth. Now you work as a Manhunter, the highest post which can a human achieve in the Orb Aliance. Your job is to hunt down all humans who, in some way, have wronged the Aliance. Once you capture them, the Aliance will correct them.' FROM games WHERE igdb_id = 7696 ON CONFLICT (game_id, language_code) DO NOTHING;
