INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Dungeons & Dragons: Heroes of the Lance', 'Heroes of the Lance is a side-scrolling action game. The game used actual Dungeons & Dragons statistics, with statistics for the characters exactly as they were in the rule books. Eight heroes from the Dragonlance novels series must be assembled for the quest, and only one is visible on the screen at a time; when one on-screen hero dies, the next in line appears.' FROM games WHERE igdb_id = 8603 ON CONFLICT (game_id, language_code) DO NOTHING;
