INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Crush', 'Fight against the aliens with your pinball skills! Imagine a living pinball machine...with aliens and outlandish worlds to throw at you. And turbo-charged, speed-of-light pinball action. You control the flippers and ball speed to defeat the Slime, the Tentacloid and Scorpion. Go for the eyes! This is full-tilt, out-of-this-world action! Surrealistic graphics plus true-to-life, earsplitting arcade pinball sound. Achieve the maximum possible score of 10 less than 1 billion and the game ends with the destruction of the table and a congratulatory message. The game is the first installment in the Crush Pinball series. It was followed by three sequels, Devil''s Crush, Jaki Crush, and Alien Crush Returns.' FROM games WHERE igdb_id = 12492 ON CONFLICT (game_id, language_code) DO NOTHING;
