INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('where-in-the-world-is-carmen-sandiego-enhanced-edition', 143640, '1988-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ti6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scag6v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in the World is Carmen Sandiego? Enhanced Edition', 'In pursuing the notorious Carmen Sandiego, you start out as a rookie detective whose job is to track down a sudden crop of thieves stealing the world''s most precious treasures. After a quick print out of your assignment, you''ll be given a deadline to capture the thief that stole the artifact using clues dealing with your knowledge of geography. Where in the world is Carmen Sandiego? Enhanced edition features spiffy VGA graphics, good sound effects, joystick support, and a convenient menu bar that''s static even in-game. There''s also the usual Hall of Fame, Detective Roster, and a Dossier profiling 10 suspects. If you''re into edutainment with as little fuss as possible, Where in the world is Carmen Sandiego? is just the game you''ve been looking for and more. You may, in fact, be playing numerous games after arresting Carmen because it''s different each time you play.' FROM games WHERE igdb_id = 143640 ON CONFLICT (game_id, language_code) DO NOTHING;
