INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Gaiden', 'Ninja Action! The stage is set for conspiracy, mystery and evil in America. Come with Ninja Ryu as he takes you on his fateful journey. Tecmo''s unique cinema display system develops the story stage by stage. You piece together the puzzle, while watching the movie-like graphics. Decide what action to take. Use the secret sword and items collected during the action scenes to fight your way to the goal!' FROM games WHERE igdb_id = 7558 ON CONFLICT (game_id, language_code) DO NOTHING;
