INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Image Fight', 'On a fateful day in 20XX, the Earth''s moon exploded into four large fragments and a multitude of meteors. Aliens from afar had succeeded in destroying the West''s moon base. One after another, mankind''s other military industrial space complexes were being lost. What mankind dreaded had come to pass. Scores of unidentified fighters were in the area. In addition, the moon''s main computer, still intact after the explosion, had a strange vegetation coiled around it. Their trademark evil exploits being a dead giveaway, invaders from the Boondoggle Galaxy had arrived to take over the Earth. To counter these evil forces, leading scientists from all over the globe created the "OF-1" Fightership. Combat pilots depart the Earth to fend off the invaders and earn everlasting glory.' FROM games WHERE igdb_id = 10452 ON CONFLICT (game_id, language_code) DO NOTHING;
