INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blaster Master', 'You''ve fallen down a hidden manhole into a world of creatures so terrifying they''d scare the rats away. You can panic and perish, or blast your way through an endless maze of tunnels, searching for the secret passages to your escape. And that''s the easy part. Because the Masters of the Caverns lay waiting - prehistoric creatures so powerful, so gigantic, they literally fill your screen! So load your arsenal and get ready for Blaster Master.' FROM games WHERE igdb_id = 2367 ON CONFLICT (game_id, language_code) DO NOTHING;
