INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('leisure-suit-larry-2-goes-looking-for-love-in-several-wrong-places', 8656, '1988-10-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kcf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arix8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leisure Suit Larry 2: Goes Looking for Love (in Several Wrong Places)', 'Leisure Suit Larry Goes Looking for Love (In Several Wrong Places) is the second game in Al Lowe''s Leisure Suit Larry series. Continuing the plot of the previous game, the swinging single Larry Laffer has finally found his true love and is happily living with her. Right? Wrong!.. Because Larry is mercilessly thrown out by his great love and is left all alone, penniless, and womanless, in Los Angeles. Accidentally, Larry comes into contact with KGB agents who will pursue him all over the globe from now on. And there is also the evil doctor Noontonyt plotting evil schemes on a remote tropical island... Looks like Larry will have to forget about his women-related problems for now... or is it so? The second game in the series introduces an improved engine (allowing for full-screen graphics and mouse control for movement). As opposed to the first game, which relied on exploration of one large area, the sequel has a more linear progression, the player being continuously taken to new locations as dictated by the plot. There are less puzzles in this installment than in the previous game; however, the number of ways to die has increased, danger awaiting Larry in most places he visits.' FROM games WHERE igdb_id = 8656 ON CONFLICT (game_id, language_code) DO NOTHING;
