INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Ranger', 'A Master Race from Outer Space Threatens the Free World! With the zapping of ray guns and the cries of Zombie Women, Rocket Ranger brings all the action, romance, thrills, and spills of the Saturday morning serial! The action begins with an urgent message from the future. . . a future that saw the Nazis win Word War II! An underground group of scientists in the 21st century risk their lives to send you a jet propelled rocket suit, ray gun and secret decoder wheel. Skillfully used against a cunning and ruthless foe, these devices help you change history and save mankind!' FROM games WHERE igdb_id = 5486 ON CONFLICT (game_id, language_code) DO NOTHING;
