INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gain-ground', 3129, '1988-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6z34.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30iq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gain Ground', 'In Gain Ground, players control one of a set of characters at a time. There are twenty characters, each with different weapons. To beat a level, players must reach the exit point with at least one character or destroy all enemies on the level before time runs out. Littered across the level are captive characters, which can be rescued by walking over, then escorting the controlled character to the exit point. If a player controlled character is killed, that character turns into a captive, except that they will disappear if the next active player controlled character dies, exits the level without them, or the player has no characters left in their party. The game is over when all controlled characters in the party are killed without any reaching the exit. However, there are three continues which allow a player to restart the level with their original three characters. There are 40 levels in the arcade version of the game. The Master System and the Genesis/Mega Drive have 50 levels in the game.' FROM games WHERE igdb_id = 3129 ON CONFLICT (game_id, language_code) DO NOTHING;
