INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impossible Mission II', 'You have 8 hours to prevent Elvin, a psychotic genius from destroying the world in this sequel to the highly successful Impossible Mission. Enter Elvin''s tower fortress, avoid his robots, assemble security combinations for each tower, recover musical sequences and tie them together into a full melody to reach Elvin''s central control room.' FROM games WHERE igdb_id = 12154 ON CONFLICT (game_id, language_code) DO NOTHING;
