INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Sharks', 'Card Shark is a a game about playing cards where the player can select from three different games: poker, hearts and blackjack. Poker is additionally divided into five card draw poker, seven stud poker and hold''em poker. He can play as up to three players from six available opponents featuring such characters as Michail Gorbachev, Ronald Reagan and Margret Thatcher. The aim is simple: the players start with a set amount of money each and the one who takes all the opponent''s money wins.' FROM games WHERE igdb_id = 92862 ON CONFLICT (game_id, language_code) DO NOTHING;
