INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('1943-kai-midway-kaisen', 39865, '1988-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6boo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nq2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1943 Kai: Midway Kaisen', 'This updated version was released exactly one year after the original game''s debut. 1943 Kai is an enhanced, "wild" version of 1943 that was made only available in Japan under the name 1943 Kai: Midway Kaisen (or 1943改: ミッドウェイ海戦). Most of the graphics and sounds have been reworked, the weapons have been made more extreme and some fairly strange things (laser-firing WWII planes and ships that run on ground) have been added. The trademark P-38 has been replaced with a biplane, the Boeing-Stearman Model 75.' FROM games WHERE igdb_id = 39865 ON CONFLICT (game_id, language_code) DO NOTHING;
