INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wayne Gretzky Hockey', 'Face off with "The Great One", number "99", Wayne Gretzky, nine-time winner of the NHL''s MVP award and all-time hockey great. Designed with Wayne and other hockey professionals, this riveting simulation is packed with all the excitement and hard-hitting action that could be squeezed into a computer. From the adrenaline rush of a breakaway goal to the tension of sudden death overtime, Wayne Gretzky Hockey takes you onto the ice for the ultimate test of skill.' FROM games WHERE igdb_id = 15509 ON CONFLICT (game_id, language_code) DO NOTHING;
