INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-manhole', 15066, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wlk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnud.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Manhole', 'A world of epic wonder and whimsical magic. A fantastic world where every character comes alive and every new hallway leads to another wild dream. Just point and click. Soon you''ll find yourself shooting down a winding waterway with Rejan Elephant. Click again and you''re climbing to the top of the rook tower to great Molly Rhinoceros. Click on Mr. Rabbit''s dresser drawer and moments later you''re flipping through the pages of his noisy ABC book. Or you''re suddenly transported to dine with that esteemed soul-cat, Mr. Dragon. So let the child in your home become the main character in a journey through an unforgettable land. A land where imaginations run wild and creativity is as close as the next wonderful doorway. Though officially for children, The Manhole has bright colors, magical locales, and cheerful adventure to delight players of all ages. Follow Mr. Rabbit through the manhole and into one of the most wondrous make-believe worlds you''ll ever find. Your adventures under the manhole will take you to many odd places -- in this game, the journey is much more important than the destination.' FROM games WHERE igdb_id = 15066 ON CONFLICT (game_id, language_code) DO NOTHING;
