INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('armalyte', 13795, '1988-12-31', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/l1frrwzh2cwse0qvrf4k.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armalyte', 'The aim of Armalyte is to progress to the end of a long, horizontally-scrolling level where the screen will cease scrolling and battle will commence with a Boss. Beating the Boss allows the player to progress to the next level. There are eight levels in all. Smaller Bosses are encountered midway through each level and these also have to be beaten to progress further.  During each level the player encounters numerous small enemy ships, many of which fly in fixed formation. Levels also feature scenery which can destroy the player''s ship if touched. Weapons can be upgraded through an upgrade system.' FROM games WHERE igdb_id = 13795 ON CONFLICT (game_id, language_code) DO NOTHING;
