INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legendary Axe', 'You are Gogan, a muscular powerhouse with enough guts to enter the Pits of Madness. Your mission: rescue the beautiful red-haired Flare. You are strong, but you also have Sting, a sacred axe to help you battle strange creatures and the savage cult of Jagu, fighting through mountain, jungle and cave environments to reach the lovely maiden.' FROM games WHERE igdb_id = 42121 ON CONFLICT (game_id, language_code) DO NOTHING;
