INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atf-advanced-tactical-fighter', 13344, '1988-12-31', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gezoj1alw3ydcxafxatr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ATF: Advanced Tactical Fighter', 'The display is a third-person view showing the player''s ATF, which remains stationary on screen as the scenery scrolls past it, which takes up most of the screen. A head-up display is superimposed on the main screen; this shows engine thrust, the ATF''s speed, ground height and altitude, along with the missile system available, direction of flight and a target''s range and bearing.  The right-hand side is devoted to the "on-board flight computer" which shows enemy positions on a world map, the status of weapon systems and the ATF itself. Above the flight computer display is a panel which shows the score and number of lives left.' FROM games WHERE igdb_id = 13344 ON CONFLICT (game_id, language_code) DO NOTHING;
