INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rambo', 'Rambo is a side scrolling platform game where the player controls Rambo with his mission to Vietnam. The game starts at the military base before getting sent to Vietnam. In Vietnam, Rambo has to fight animals in the jungles, swamps, and caves like wasps, snakes, fish, tigers, bats, spiders, birds, apes and flamingos. Before making his way to the POW camp he has to fight guards and mercenaries that can kick and shoot him, all wearing different color shirts depending on how powerful they are. The game also requires the player to navigate a complex map requiring the player to find North and South points on the ground to go up and down levels as well as East and West by moving Rambo to the edge of the screen. There are 6 different weapons that Rambo can pick up that are knife, throwing knife, bow and arrow, bow and exploring arrow, gun, and hand grenade. All the weapons but the knife has limited ammo which is collected from killed enemies. There is also health vile that restores health as well as mission specific items that Rambo must find to complete some missions. The game uses password save that can be retrieved when talking to any person.' FROM games WHERE igdb_id = 48210 ON CONFLICT (game_id, language_code) DO NOTHING;
