INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbarian II: The Dungeon of Drax', 'Barbarian II: The Dungeon of Drax is a video game first published in 1988 for various home computers. It was also released as Axe of Rage in North America. The game is the sequel to Barbarian: The Ultimate Warrior (Death Sword in North America), which was published in 1987. In Barbarian II, the player controls a princess or barbarian character, exploring the game world to locate and defeat an evil wizard. The game''s plot is an extension of its predecessor, although the gameplay is different. While the first game offers two players the opportunity for virtual head-to-head combat, the second is solely a single-player adventure with fewer fighting moves.' FROM games WHERE igdb_id = 4640 ON CONFLICT (game_id, language_code) DO NOTHING;
