INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R.C. Pro-Am', 'Presented in an overhead isometric perspective, a single player races a radio-controlled car around a series of tracks. The objective of each track is to qualify for the next race by placing in the top three racers. Players collect items to improve performance, and they must avoid a variety of hazards such as rain puddles and oil slicks. It is an example of a racing game which features vehicular combat, in which racers can use missiles and bombs to temporarily disable opposing vehicles. The game distanced itself from earlier racing titles by using an overhead, instead of a first-person, perspective. Reviews have cited it as inspiration for future games such as Super Off Road, Rock n'' Roll Racing, and the Mario Kart series. It has appeared in many "top games of all time" lists and is regarded as one of the best titles in the NES library.' FROM games WHERE igdb_id = 9155 ON CONFLICT (game_id, language_code) DO NOTHING;
