INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Guardian Legend', 'In The Guardian Legend, the player controls the female guardian of Earth, a "highly sophisticated aerobot transformer". The player''s mission is to infiltrate Naju, a large planet-like object which aliens sent hurtling towards the Earth. While inside, the player must activate ten safety devices in order to initialize Naju''s self-destruct mechanism and destroy the alien world before it reaches Earth. Five hostile tribes of alien lifeforms are vie for control of territories within Naju,and the player needs to fight through them to successfully activate the switches and escape.' FROM games WHERE igdb_id = 48058 ON CONFLICT (game_id, language_code) DO NOTHING;
