INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dangerous-dave', 2471, '1988-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ndh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/f61szi0oz4gsh3r83ma2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangerous Dave', 'The object of the game was to collect gold cups to move on to the next level. Since the original 1988 publishing of Dangerous Dave on UpTime, there have been three sequels and three ports of the original to other platforms. The idea of Dangerous Dave came to John Romero under the influence of Super Mario. There are definitely similarities that are easily noticeable, such as the secret levels, the level design, the monsters, and the jumping. The mission is to guide Dave through ten levels, collecting trophies in the hideout of his enemy, Clyde. Romero says that among all Dangerous Dave sequels Dangerous Dave in the Haunted Mansion is "the best Dave ever created". In 2008 Dangerous Dave in the Haunted Mansion was ported to cell phones.' FROM games WHERE igdb_id = 2471 ON CONFLICT (game_id, language_code) DO NOTHING;
